"""Emit primitive domains directly from validated parameter declarations."""

from __future__ import annotations

import json
import subprocess
from typing import TYPE_CHECKING, Any

from check_format import find_clang_format, pinned_major
from parameter_values import CPP_KEYWORDS, INTEGER, NUMERIC, exact_number, invalid

if TYPE_CHECKING:
    from pathlib import Path

PREAMBLE = (
    "// SPDX-FileCopyrightText: 2026 Ervins Strauhmanis\n"
    "// SPDX-License-Identifier: MPL-2.0\n"
    "// Generated by tools/generate_spec.py from the reviewed CLI/method contracts.\n"
    "#pragma once\n"
    '#include "docenhance/core/range.hpp"\n'
    "#include <array>\n#include <cstdint>\n#include <optional>\n"
    "#include <string_view>\n"
    "namespace docenhance::methods {\n"
)

DOMAIN_TYPE = """template <typename T, typename Default = T> struct ParameterDomain {
    T minimum;
    T maximum;
    Default default_value;
    bool odd;
    [[nodiscard]] constexpr bool contains(T value) const noexcept {
        return core::in_range(value, minimum, maximum, odd);
    }
};
"""


def option_id(option: dict[str, Any]) -> str:
    """Use the canonical long spelling as the C++ option/domain identifier."""
    name: str = option["name"]
    identity = name.removeprefix("--").replace("-", "_")
    if identity in CPP_KEYWORDS or identity == "count_sentinel":
        invalid(f"{name}: reserved generated option identity")
    return identity


def numeric_literal(text: str, *, integer: bool) -> str:
    """Keep rational declarations exact until conversion into the declared C++ type."""
    value = exact_number(text)
    if integer:
        return f"{int(value)}U"
    # Round the exact final rational once. Rounding numerator/denominator before division can
    # change a bound by one ULP or overflow an intermediate even when the final value is finite.
    return float(value).hex()


def numeric_domain(option: dict[str, Any]) -> str:
    """Emit scalar defaults directly; auto/source unions retain typed optional defaults."""
    integer = option["kind"] in INTEGER
    type_name = "std::uint32_t" if integer else "double"
    domain_type = (
        f"{type_name}, std::optional<{type_name}>"
        if option["kind"] in {"auto_or_integer", "source_or_decimal"}
        else type_name
    )
    low = numeric_literal(option["min"], integer=integer)
    high = numeric_literal(option["max"], integer=integer)
    fallback = option.get("default")
    # Grid dimensions have the same domain, but each axis retains its own authored default.
    defaults = fallback.split("x") if option["kind"] == "grid" and fallback else [fallback]
    names = ["columns", "rows"] if option["kind"] == "grid" else [""]
    lines = []
    for suffix, default in zip(names, defaults, strict=True):
        initial = (
            numeric_literal(default, integer=integer)
            if default is not None and default not in {"auto", "source"}
            else "std::nullopt"
        )
        name = option_id(option) + ("_" + suffix if suffix else "")
        odd = str(option["kind"] == "odd_integer").lower()
        lines.append(
            f"inline constexpr ParameterDomain<{domain_type}> {name}_domain"
            f"{{.minimum = {low}, .maximum = {high}, .default_value = {initial}, .odd = {odd},}};\n"
        )
    return "".join(lines)


def choice_domain(option: dict[str, Any]) -> str:
    """Generate a closed selector type and its spelling table without an open fallback."""
    identity = option_id(option)
    enum_name = "".join(word.capitalize() for word in identity.split("_")) + "Value"
    # Numeric spellings and C++ keywords still receive unambiguous valid enumerators.
    values = ["value_" + value.replace("-", "_") for value in option["values"]]
    if len(set(values)) != len(values):
        invalid(f"{option['name']}: colliding generated choice identities")
    text = f"enum class {enum_name} {{ {', '.join(values)} }};\n"
    text += f"inline constexpr auto {identity}_values = std::to_array<std::string_view>({{"
    text += ", ".join(json.dumps(value) for value in option["values"]) + ",});\n"
    return text


def render_domains(options: list[dict[str, Any]]) -> str:
    """Render generated primitive validators; no app types, effects or method headers appear."""
    validate_symbols(options)
    text = PREAMBLE + DOMAIN_TYPE
    for option in options:
        if option["kind"] in NUMERIC:
            text += numeric_domain(option)
        elif option["kind"] == "choice":
            text += choice_domain(option)
    return text + "} // namespace docenhance::methods\n"


def validate_symbols(options: list[dict[str, Any]]) -> None:
    """Refuse distinct authored names that would alias a generated domain or enum type."""
    symbols: set[str] = set()
    for option in options:
        identity = option_id(option)
        names = []
        if option["kind"] in NUMERIC:
            suffixes = ["_columns", "_rows"] if option["kind"] == "grid" else [""]
            names = [identity + suffix + "_domain" for suffix in suffixes]
        elif option["kind"] == "choice":
            names = [
                "".join(word.capitalize() for word in identity.split("_")) + "Value",
                identity + "_values",
            ]
        if symbols.intersection(names):
            invalid(f"{option['name']}: colliding generated declaration")
        symbols.update(names)


def format_outputs(outputs: dict[Path, str], root: Path) -> dict[Path, str]:
    """Canonicalize generated C++ in memory with the existing pinned formatter and stylesheet."""
    major = pinned_major()
    executable, seen = find_clang_format(major)
    if executable is None:
        invalid(f"Generation requires clang-format {major} (found: {seen})")
    result = dict(outputs)
    for path, text in outputs.items():
        if path.suffix not in {".hpp", ".cpp"}:
            continue
        formatted = subprocess.run(
            [executable, f"--style=file:{root / '.clang-format'}", f"--assume-filename={path}"],
            input=text,
            text=True,
            capture_output=True,
            check=True,
            timeout=10,
        )
        result[path] = formatted.stdout
    return result
